create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key default gen_random_uuid(),username text unique not null,display_name text not null,avatar_url text,country text,gender text,birth_date date,bio text,level int default 1,xp bigint default 0,vip_level int default 0,coins bigint default 0,diamonds bigint default 0,followers_count bigint default 0,following_count bigint default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists user_roles(user_id uuid references profiles(id) on delete cascade,role text not null,primary key(user_id,role));
create table if not exists sessions(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,refresh_hash text unique,expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz default now());
create table if not exists follows(follower_id uuid references profiles(id) on delete cascade,following_id uuid references profiles(id) on delete cascade,created_at timestamptz default now(),primary key(follower_id,following_id));
create table if not exists blocks(blocker_id uuid references profiles(id) on delete cascade,blocked_id uuid references profiles(id) on delete cascade,primary key(blocker_id,blocked_id));
create table if not exists rooms(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles(id),name text not null,description text,cover_url text,background_url text,country text,language text,category text,announcement text,is_private boolean default false,password_hash text,max_listeners int default 500,status text default 'live',level int default 1,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists room_members(room_id uuid references rooms(id) on delete cascade,user_id uuid references profiles(id) on delete cascade,role text default 'listener',seat int,muted boolean default false,banned_until timestamptz,joined_at timestamptz default now(),primary key(room_id,user_id));
create table if not exists gifts(id uuid primary key default gen_random_uuid(),name text not null,icon_url text,animation_url text,sound_url text,price bigint not null,currency text default 'coins',required_level int default 1,active boolean default true,created_at timestamptz default now());
create table if not exists gift_transactions(id uuid primary key default gen_random_uuid(),sender_id uuid references profiles(id),receiver_id uuid references profiles(id),room_id uuid references rooms(id),gift_id uuid references gifts(id),quantity int default 1,total bigint not null,reference text unique not null,status text default 'completed',created_at timestamptz default now());
create table if not exists wallet_ledger(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),type text not null,amount bigint not null,currency text not null,reference text unique not null,balance_after bigint,metadata jsonb default '{}',created_at timestamptz default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(),name text not null,icon text,sort_order int default 0,active boolean default true);
create table if not exists events(id uuid primary key default gen_random_uuid(),name text not null,description text,icon text,badge text,starts_at timestamptz,ends_at timestamptz,reward jsonb default '{}',active boolean default true);
create table if not exists room_messages(id uuid primary key default gen_random_uuid(),room_id uuid references rooms(id) on delete cascade,sender_id uuid references profiles(id),body text,created_at timestamptz default now(),deleted_at timestamptz);
create table if not exists direct_messages(id uuid primary key default gen_random_uuid(),sender_id uuid references profiles(id),receiver_id uuid references profiles(id),body text,media_url text,created_at timestamptz default now(),deleted_at timestamptz);
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),type text,title text,body text,data jsonb default '{}',read_at timestamptz,created_at timestamptz default now());
create table if not exists reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references profiles(id),target_user_id uuid references profiles(id),room_id uuid references rooms(id),type text,reason text,status text default 'open',reviewer_id uuid,reviewed_at timestamptz,created_at timestamptz default now());
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid,action text not null,entity text,entity_id text,metadata jsonb default '{}',created_at timestamptz default now());